import{_ as e,c as o,o as n,ag as r}from"./chunks/framework.Bzez9NG9.js";const a="/space/img/2new_job_menu.png",b=JSON.parse('{"title":"Jobs","description":"Create and schedule SPACE jobs for documentation, log synchronization, Python scripts, and TM1 Git updates, and review execution results.","frontmatter":{"title":"Jobs","description":"Create and schedule SPACE jobs for documentation, log synchronization, Python scripts, and TM1 Git updates, and review execution results.","keywords":["cron","background tasks","email notifications"],"outline":"deep"},"headers":[],"relativePath":"doc/configuration/jobs.md","filePath":"doc/configuration/jobs.md"}'),s={name:"doc/configuration/jobs.md"};function d(i,t,l,c,h,u){return n(),o("div",null,t[0]||(t[0]=[r('<h1 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h1><p>Use the <strong>Jobs</strong> tab to schedule background tasks such as log syncs, documentation refreshes, Python automations, and TM1 Git updates.</p><p><img src="'+a+'" alt="New job menu" data-zoomable=""></p><h2 id="jobs-table" tabindex="-1">Jobs table <a class="header-anchor" href="#jobs-table" aria-label="Permalink to &quot;Jobs table&quot;">​</a></h2><ul><li><strong>Job name</strong> – descriptive label (click to edit).</li><li><strong>Status</strong> – Active jobs run on the defined schedule; Disabled jobs are paused. Use the toggle on each job to enable/disable.</li><li><strong>Last run / Last result</strong> – quick health check for the most recent execution.</li><li><strong>Context menu</strong> – run on demand, review history, or delete a job.</li></ul><h2 id="creating-a-job" tabindex="-1">Creating a job <a class="header-anchor" href="#creating-a-job" aria-label="Permalink to &quot;Creating a job&quot;">​</a></h2><p>Select <strong>New job</strong> and choose the required job type. Every job shares a few common fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Connection</strong></td><td>TM1 server used for the job (not shown for Python/Git jobs that do not require TM1).</td></tr><tr><td><strong>Job name</strong></td><td>Auto-generated but editable; use meaningful names for notifications.</td></tr><tr><td><strong>Scheduled toggle</strong></td><td>Enable to run on a cadence; disable for manual execution only.</td></tr><tr><td><strong>Email notifications</strong></td><td>Comma-separated list of recipients.</td></tr><tr><td><strong>Notification type</strong></td><td>Choose Success + Error, Success only, Error only, or No notifications.</td></tr><tr><td><strong>Include job details</strong></td><td>Attach job metadata to notification emails.</td></tr></tbody></table><p>Scheduling options apply to every job:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Schedule</strong></td><td>Cron expression that defines when the job runs. Cron uses five fields (minute, hour, day of month, month, day of week). For example, <code>0 1 * * *</code> runs daily at 1:00 AM, while <code>30 5 * * 1-5</code> runs at 5:30 AM on weekdays.</td></tr><tr><td><strong>Schedule templates</strong></td><td>Quick presets (Everyday 1 PM, Every weekday 5:30 AM, Every Saturday at noon, Every hour, Every 30 minutes) that auto-populate the Schedule field with the appropriate cron string. Select a preset or manually enter a custom cron expression to match your scheduling needs.</td></tr></tbody></table><p>Each job type adds extra fields. The log-focused jobs share the same inputs.</p><table tabindex="0"><thead><tr><th>Job type</th><th>Additional fields</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Documentation update</strong></td><td>Connection (required)</td><td>Refreshes model documentation for the selected TM1 server.</td></tr><tr><td><strong>Audit log update</strong></td><td>Sync interval (hours), Retain logs (months), Connection (required)</td><td>Pulls TM1 audit logs into SPACE on the defined cadence.</td></tr><tr><td><strong>Server log update</strong></td><td>Sync interval (hours), Retain logs (months), Connection (required)</td><td>Pulls TM1 server logs into SPACE on the defined cadence.</td></tr><tr><td><strong>Transaction log update</strong></td><td>Sync interval (hours), Retain logs (months), Connection (required)</td><td>Pulls TM1 transaction logs into SPACE on the defined cadence.</td></tr><tr><td><strong>Python script</strong></td><td>Script file path, Arguments</td><td>Runs a stored Python script with optional parameters.</td></tr><tr><td><strong>Git update</strong></td><td>Git repository, Action (Pull, Push, etc.)</td><td>Automates sync tasks for repositories in the SPACE TM1 Git module.</td></tr></tbody></table><p>Configure the fields, test if necessary, then click <strong>Create</strong>. Jobs can be edited later to adjust schedules, notifications, or parameters.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./connections.html">Connections</a> covers job credentials.</li><li><a href="./content.html">Content</a> covers cached documentation and logs.</li><li><a href="./../python/">Python</a> covers scripts.</li><li><a href="./../planning-analytics/git.html">Git</a> covers the SPACE TM1 Git module, separate from Python/JupyterLab Git integration.</li></ul>',15)]))}const p=e(s,[["render",d]]);export{b as __pageData,p as default};
